'use strict';
let composition={title:'你先弹，我来接',bpm:90,instrument:'piano',notes:[],response:[]},audio=null,voices=new Set(),held=new Map(),origin=null,playTimer=null,playing=false,playStart=0;const cvs=document.querySelector('#timeline'),ctx=cvs.getContext('2d'),pitches=[60,62,64,65,67,69,71,72],keys='asdfghjk';
function ensureAudio(){if(!audio||audio.state==='closed')audio=new AudioContext();return audio.resume()}
function voice(pitch,time,duration,velocity,instrument='piano'){const osc=audio.createOscillator(),gain=audio.createGain();osc.type=instrument==='bell'?'sine':instrument==='pad'?'triangle':'triangle';osc.frequency.value=440*2**((pitch-69)/12);gain.gain.setValueAtTime(0,time);gain.gain.linearRampToValueAtTime(velocity*.18,time+.012);gain.gain.exponentialRampToValueAtTime(.001,time+duration+.18);osc.connect(gain);gain.connect(audio.destination);osc.start(time);osc.stop(time+duration+.22);voices.add(osc);osc.onended=()=>{voices.delete(osc);gain.disconnect();osc.disconnect()}}
function stop(){clearTimeout(playTimer);playing=false;for(const o of voices){try{o.stop()}catch(e){}}voices.clear();document.querySelector('#play').textContent='播放合奏';draw()}
function draw(){ctx.clearRect(0,0,450,100);let end=Math.max(8,...composition.notes.map(n=>n.time+n.duration),...composition.response.map(n=>n.time+n.duration));ctx.strokeStyle='#ffffff10';for(let i=1;i<8;i++){ctx.beginPath();ctx.moveTo(i*450/8,0);ctx.lineTo(i*450/8,100);ctx.stroke()}for(const [notes,color]of[[composition.notes,'#a8dfe5'],[composition.response,'#eac38c']]){ctx.fillStyle=color;for(const n of notes){let x=10+n.time/end*425,y=83-(n.pitch-48)/36*69,w=Math.max(4,n.duration/end*425);ctx.beginPath();ctx.moveTo(x+2,y);ctx.lineTo(x+w-2,y);ctx.quadraticCurveTo(x+w,y,x+w,y+2);ctx.lineTo(x+w,y+3);ctx.quadraticCurveTo(x+w,y+5,x+w-2,y+5);ctx.lineTo(x+2,y+5);ctx.quadraticCurveTo(x,y+5,x,y+3);ctx.lineTo(x,y+2);ctx.quadraticCurveTo(x,y,x+2,y);ctx.closePath();ctx.fill()}}ctx.font='10px -apple-system,sans-serif';ctx.fillStyle='#a8dfe5';ctx.fillText('你',10,15);ctx.fillStyle='#eac38c';ctx.fillText('AI',32,15);if(!composition.notes.length){ctx.fillStyle='#a8b4c4';ctx.font='13px sans-serif';ctx.fillText('轻触琴键，留下你的第一句旋律',112,55)}document.querySelector('#count').textContent=composition.notes.length+' 个音符';document.querySelector('#title').textContent=composition.title}
async function begin(pitch,el){if(held.has(pitch)||!loaded||composition.notes.length>=64)return;if(playing)stop();if(origin===null)origin=performance.now();let time=(performance.now()-origin)/1000;if(time>30){status('这一句已满 · 点 AI 接奏，或重新弹奏');return}held.set(pitch,{time,start:performance.now(),el});el?.classList.add('on');try{await ensureAudio();if(stopped||!held.has(pitch))return;voice(pitch,audio.currentTime,.4,.8);status('正在记录你的旋律 · A S D F G H J K 也能弹奏')}catch(e){held.delete(pitch);el?.classList.remove('on');status('无法启动声音，请重试')}}
function end(pitch){let n=held.get(pitch);if(!n)return;held.delete(pitch);n.el?.classList.remove('on');composition.notes.push({pitch,time:+n.time.toFixed(3),duration:+Math.max(.1,Math.min(2,(performance.now()-n.start)/1000)).toFixed(3),velocity:.8});composition.response=[];draw()}
pitches.forEach((p,i)=>{let b=document.createElement('button');b.className='key';b.textContent=['C','D','E','F','G','A','B','C'][i];b.setAttribute('aria-label','音符 '+p);b.onpointerdown=e=>{b.setPointerCapture(e.pointerId);begin(p,b)};b.onpointerup=()=>end(p);b.onpointercancel=()=>end(p);document.querySelector('#keys').append(b)});
addEventListener('keydown',e=>{if(e.target.matches('input,textarea')||e.repeat)return;let i=keys.indexOf(e.key.toLowerCase());if(i>=0){e.preventDefault();begin(pitches[i],document.querySelectorAll('.key')[i])}});addEventListener('keyup',e=>{let i=keys.indexOf(e.key.toLowerCase());if(i>=0)end(pitches[i])});addEventListener('blur',()=>{for(const p of held.keys())end(p);stop()});
document.querySelector('#play').onclick=async()=>{if(playing){stop();return}let notes=[...composition.notes,...composition.response];if(!notes.length)return status('先弹奏一段旋律');await ensureAudio();if(stopped)return;playing=true;document.querySelector('#play').textContent='停止播放';for(const n of notes)voice(n.pitch,audio.currentTime+.05+n.time,n.duration,n.velocity,composition.instrument);playTimer=setTimeout(stop,(Math.max(...notes.map(n=>n.time+n.duration))+.4)*1000);status('青色是你的旋律 · 金色是 AI 的回应')};
document.querySelector('#clear').onclick=()=>{if(!loaded)return;stop();composition.notes=[];composition.response=[];origin=null;draw();status('已清空当前草稿 · 保存后才覆盖设备记录')};document.querySelector('#bpm').onchange=e=>{composition.bpm=Math.max(50,Math.min(160,Number(e.target.value)||90));e.target.value=composition.bpm};document.querySelector('#save').onclick=()=>saveState(composition);
document.querySelector('#generate').onclick=()=>{if(!composition.notes.length)return status('先弹几个音，让 AI 听到你的想法');generate('duet',{notes:composition.notes,bpm:composition.bpm},r=>{if(!Array.isArray(r.notes)||r.notes.length>128||r.notes.some(n=>![n.pitch,n.time,n.duration,n.velocity].every(Number.isFinite)||n.pitch<48||n.pitch>84||n.time<0||n.time>32||n.duration<.1||n.duration>2||n.velocity<.1||n.velocity>1))throw Error('模型返回的旋律格式无效，原旋律已保留');composition.response=r.notes;composition.title=String(r.title||'我们的合奏').slice(0,40);composition.instrument=['piano','bell','pad'].includes(r.instrument)?r.instrument:'piano';composition.bpm=r.bpm;document.querySelector('#bpm').value=r.bpm;draw();status('AI 回应已到 · 点击播放合奏')})};
(async()=>{try{composition=await AtomApp.load(composition);if(!Array.isArray(composition.notes)||!Array.isArray(composition.response))throw Error('存档格式异常');loaded=true;document.querySelector('#bpm').value=composition.bpm;status('轻触琴键 · 弹完后邀请 AI 接奏')}catch(e){status('读取失败 · 请重新打开，原合奏不会被覆盖')}draw();document.querySelector('#generate').disabled=!loaded;AtomApp.ready()})();AtomApp.onSuspend(()=>{stop();held.clear();if(audio)audio.close()});
